#![allow(dead_code)] // consumers arrive module by module; blanket dropped as they land
//! Icon geometry copied verbatim from `lucide-solid@1.23.0` (ISC licensed) -
//! the same package `apps/desktop` imports, so the shapes match by
//! construction rather than by transcription.
//!
//! # Deviations from the raw lucide source
//!
//!   1. `stroke-width` is a property of the *call site*, not of the icon.
//!      `icons.tsx` renders `stroke-width={props.strokeWidth ?? 2}`: the tool
//!      rail passes `1.6`, the option bars `1.75` or `1.5`, an unqualified
//!      `<Icon />` gets lucide's `2`. Each constant below carries the width
//!      its **primary** consumer uses - the rail's tool set first, because
//!      that is the part already measured against a baseline. When a second
//!      call site needs a different width for the same glyph, ask for it with
//!      [`with_stroke`] instead of editing the constant.
//!   2. `stroke="currentColor"` -> `stroke="#ffffff"`. GPUI rasterises an SVG's
//!      alpha channel and tints it with the element's `text_color`, so the
//!      stroke value is discarded - a literal colour avoids relying on
//!      `currentColor` reaching the SVG parser.
//!   3. The `class="lucide lucide-*"` attribute, the preview's
//!      `style="background-color: #fff; ..."`, and the licence comment are
//!      stripped; none of them render.
//!
//! Render with `Icon::default().data(TOKEN)`; no `AssetSource` registration is
//! needed, which is also why this crate does not depend on gpui-kit's bundled
//! Lucide catalogue agreeing with `lucide-solid`'s version.
//!
//! # Provenance
//!
//! Generated by the web build's `tools/gen_icons.mjs`, which decodes each icon
//! module's base64 `@preview` SVG and resolves component names through
//! `dist/esm/lucide-solid.mjs`. Reading that file is not optional: lucide
//! renamed a batch of icons, so `AlignLeft` is really `text-align-start.mjs`
//! and no amount of guessing a file name from the component name finds it.
//! The generator also carries a `--check` mode that grades disagreements rather
//! than counting them: a different path is a different icon and always fails,
//! while the same path at a different stroke-width only fails if the constant
//! is one the baseline-verified chrome actually references.

use std::collections::HashMap;
use std::sync::Mutex;

/// Re-render `svg` at a different `stroke-width`, handing back a cached copy.
///
/// The constants below are pinned to one width each (see the module docs), so
/// a call site that wants a width other than the baked-in one - the same icon
/// at `1.75` in an option bar and `2` in the title bar, say - asks here:
///
/// ```ignore
/// Icon::default().data(icons::with_stroke(icons::CHEVRON_DOWN, 2.0))
/// ```
///
/// Results are interned by source pointer and width, so a repeated call
/// returns the same `&'static [u8]` and GPUI parses the SVG once per distinct
/// combination rather than once per frame. A constant carrying no
/// `stroke-width` attribute at all is returned unchanged, since there is
/// nothing to rewrite.
pub fn with_stroke(svg: &'static [u8], width: f32) -> &'static [u8] {
    #[allow(clippy::type_complexity)]
    static CACHE: Mutex<Option<HashMap<(usize, String), &'static [u8]>>> = Mutex::new(None);

    let target = format!("stroke-width=\"{}\"", fmt_width(width));
    let key = (svg.as_ptr() as usize, target.clone());

    let mut guard = CACHE.lock().unwrap_or_else(|e| e.into_inner());

    let cache = guard.get_or_insert_with(HashMap::new);
    if let Some(hit) = cache.get(&key) {
        return hit;
    }
    let text = String::from_utf8_lossy(svg);
    const MARK: &str = "stroke-width=\"";
    let Some(i) = text.find(MARK) else {
        return svg;
    };
    let value_start = i + MARK.len();
    let Some(rel) = text[value_start..].find('"') else {
        return svg;
    };
    let value_end = value_start + rel + 1; // past the closing quote

    let replaced = format!("{}{}{}", &text[..i], target, &text[value_end..]);
    let out: &'static [u8] = Box::leak(replaced.into_bytes().into_boxed_slice());
    cache.insert(key, out);
    out
}

/// Write a width the way lucide does: `2`, not `2.0`.
fn fmt_width(width: f32) -> String {
    if width.fract() == 0.0 {
        format!("{}", width as i64)
    } else {
        format!("{width}")
    }
}

