#[cfg(test)]
mod tests {
    use super::*;

    /// Well-formedness pins a few well-known icons: exact first byte (`<` =
    /// 0x3c) and exact trailing bytes (`</svg>`), so a truncation or prefix
    /// corruption reddens here rather than silently rendering garbage.
    #[test]
    fn icons_are_well_formed() {
        let expected_first: u8 = b'<';
        for (name, bytes) in [
            ("UNDO", UNDO),
            ("REDO", REDO),
            ("CHEVRON_DOWN", CHEVRON_DOWN),
            ("X", X),
            ("BRUSH", BRUSH),
            ("ALIGN_BOTTOM", ALIGN_BOTTOM),
            ("CIRCLE_DASHED", CIRCLE_DASHED),
        ] {
            assert_eq!(
                bytes[0], expected_first,
                "{name} must start with '<' (got {:?})",
                bytes[0] as char
            );
            assert!(bytes.ends_with(b"</svg>"), "{name} must end with </svg>");
            let text = std::str::from_utf8(bytes).expect("icons are valid UTF-8");
            assert!(
                text.contains("stroke=\"#ffffff\""),
                "{name} must carry the white stroke from the lucide port"
            );
        }
    }

    /// `with_stroke` returns the input unchanged when no `stroke-width`
    /// attribute exists in the SVG (LOGO carries none), and rewrites it
    /// to the requested width when one does.
    #[test]
    fn with_stroke_rewrite_semantics() {
        // LOGO has no stroke-width attribute - returned unchanged.
        let same = with_stroke(LOGO, 1.75);
        assert!(
            std::ptr::eq(same.as_ptr(), LOGO.as_ptr()),
            "logo has no stroke-width; must be returned without allocation"
        );

        // UNDO carries stroke-width="1.75" - rewriting to "1.5" must change it.
        let rewritten = with_stroke(UNDO, 1.5);
        assert_ne!(
            rewritten.as_ptr(),
            UNDO.as_ptr(),
            "must produce a new buffer when rewriting"
        );
        let rw_text = std::str::from_utf8(rewritten).expect("icon is valid UTF-8");
        assert!(
            rw_text.contains("stroke-width=\"1.5\""),
            "the rewritten buffer must carry the new width"
        );
    }
}
